package com.greenocean.backend;
import com.greenocean.backend.listener.planning.*;import com.greenocean.backend.listener.live.*;import com.greenocean.backend.auth.repository.UserRepository;import com.greenocean.backend.auth.service.TokenService;import com.greenocean.backend.account.repository.AccountRepository;
import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;import org.springframework.jdbc.core.JdbcTemplate;
import org.junit.jupiter.api.*;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;
@SpringBootTest(properties={"greenocean.live-support.enabled=true","greenocean.listener-support.duration-enabled=true","greenocean.listener-support.scheduling-enabled=true","greenocean.listener-support.booking-enabled=true","greenocean.listener-support.queue-enabled=true"}) @ActiveProfiles("test") @Transactional
class PhaseN2QueueTest {
 @Autowired JdbcTemplate db;@Autowired UserRepository users;@Autowired TokenService tokens;@Autowired ListenerQueue queue;@Autowired ListenerQueueCoverage coverage;@Autowired ListenerSupportPolicy p;@Autowired LiveSupportService live;@Autowired AccountRepository accounts;
 PhaseIFixtures.Actor member,listener,staff;Instant now;UUID staffing;
 @BeforeEach void setup(){PhaseIFixtures.region(db);member=PhaseIFixtures.member(db,users,tokens);listener=PhaseIFixtures.member(db,users,tokens);staff=PhaseIFixtures.member(db,users,tokens);PhaseIFixtures.review(db,listener.id(),staff.id(),true);now=p.now();staffing=coverage.approve(staff.id(),new ListenerQueueCoverage.Window(listener.id(),now.minusSeconds(60),now.plusSeconds(14400)));live.setAvailability(listener.id(),listener.session(),0,true,null);}
 ListenerQueue.Admission input(){return new ListenerQueue.Admission(UUID.randomUUID(),null,false);}
 UUID join(){return(UUID)queue.join(member.id(),input()).get("id");}
 Map<String,Object> offer(UUID id){queue.work();return queue.view(id,member.id());}
 void clock(Instant value){db.execute("CREATE OR REPLACE FUNCTION listener_support_now() RETURNS TIMESTAMPTZ LANGUAGE SQL VOLATILE AS $$ SELECT '"+value+"'::timestamptz $$");}
 @Test @Tag("happy") void readsDoNotAdmitAndRetriesCannotRenewTwentyMinuteDeadline(){assertThat(queue.state(member.id()).get("entry")).isEqualTo(Map.of());var in=input();var q=queue.join(member.id(),in);Instant admitted=ListenerSupportPolicy.instant(q.get("admitted_at")),expires=ListenerSupportPolicy.instant(q.get("expires_at"));assertThat(Duration.between(admitted,expires)).isEqualTo(Duration.ofMinutes(20));clock(admitted.plusSeconds(10));assertThat(queue.join(member.id(),in).get("expires_at")).isEqualTo(q.get("expires_at"));assertThatThrownBy(()->queue.join(member.id(),input())).hasMessageContaining("already");}
 @Test @Tag("confused") void calendarOrProfileWithoutCurrentReadinessAndStaffingNeverCreatesQueue(){live.setAvailability(listener.id(),listener.session(),0,false,live.availability(listener.id(),listener.session()).leaseId());assertThatThrownBy(this::join).hasMessageContaining("No currently staffed");live.setAvailability(listener.id(),listener.session(),0,true,null);coverage.revoke(staff.id(),staffing);assertThatThrownBy(this::join).hasMessageContaining("No currently staffed");assertThat(db.queryForObject("SELECT count(*) FROM listener_wait_queue WHERE member_id=?",Integer.class,member.id())).isZero();}
 @Test @Tag("happy") void proposalReadinessAcceptanceAndActivationAreSeparate(){UUID id=join();var q=offer(id);assertThat(q.get("status")).isEqualTo("OFFERED");assertThat(db.queryForObject("SELECT count(*) FROM live_support_requests WHERE member_id=?",Integer.class,member.id())).isZero();var confirmed=queue.confirm(id,member.id(),new ListenerQueue.Confirmation((UUID)q.get("allocation_id")));var r=(LiveSupportView)confirmed.get("request");assertThat(r.status()).isEqualTo("REQUESTED");assertThat(r.conversationId()).isNull();assertThat(live.accept(r.id(),listener.id()).conversationId()).isNull();assertThat(live.activate(r.id(),member.id()).conversationId()).isNotNull();assertThat(((LiveSupportView)queue.confirm(id,member.id(),new ListenerQueue.Confirmation((UUID)q.get("allocation_id"))).get("request")).id()).isEqualTo(r.id());}
 @Test @Tag("malicious") void exactExpiryAndUnansweredProposalAreTerminal(){UUID id=join();var q=offer(id);clock(ListenerSupportPolicy.instant(q.get("allocation_expires_at")));assertThat(queue.get(id,member.id()).get("status")).isEqualTo("EXPIRED");assertThatThrownBy(()->queue.confirm(id,member.id(),new ListenerQueue.Confirmation((UUID)q.get("allocation_id")))).hasMessageContaining("no longer");assertThat(db.queryForObject("SELECT count(*) FROM live_support_requests WHERE member_id=?",Integer.class,member.id())).isZero();}
 @Test @Tag("creative") void parentQueueExpiryNeverDestroysTransferredIndependentRequest(){UUID id=join();var q=offer(id);var r=(LiveSupportView)queue.confirm(id,member.id(),new ListenerQueue.Confirmation((UUID)q.get("allocation_id"))).get("request");clock(ListenerSupportPolicy.instant(q.get("expires_at")).plusSeconds(1));assertThat(queue.get(id,member.id()).get("status")).isEqualTo("TRANSFERRED");assertThat(live.get(r.id(),member.id()).status()).isEqualTo("REQUESTED");assertThat(live.accept(r.id(),listener.id()).status()).isEqualTo("ACCEPTED");}
 @Test @Tag("malicious") void ownershipAndProposalIdentityPreventTheft(){UUID id=join();var q=offer(id);var other=PhaseIFixtures.member(db,users,tokens);assertThatThrownBy(()->queue.get(id,other.id())).isInstanceOf(LiveSupportException.class);assertThatThrownBy(()->queue.cancel(id,other.id())).isInstanceOf(LiveSupportException.class);assertThatThrownBy(()->queue.confirm(id,member.id(),new ListenerQueue.Confirmation(UUID.randomUUID()))).hasMessageContaining("another proposal");assertThat(queue.view(id,member.id()).toString()).doesNotContain(member.id().toString(),other.id().toString(),"email");}
 @Test @Tag("creative") void fifoSkipsExpiredProposalWithoutAutomaticRequeue(){UUID first=join();var next=PhaseIFixtures.member(db,users,tokens);UUID second=(UUID)queue.join(next.id(),input()).get("id");var q=offer(first);assertThat(q.get("status")).isEqualTo("OFFERED");assertThat(queue.view(second,next.id()).get("status")).isEqualTo("WAITING");clock(ListenerSupportPolicy.instant(q.get("allocation_expires_at")).plusSeconds(1));queue.work();assertThat(queue.view(first,member.id()).get("status")).isEqualTo("EXPIRED");assertThat(queue.view(second,next.id()).get("status")).isEqualTo("OFFERED");assertThat(db.queryForObject("SELECT count(*) FROM listener_wait_queue WHERE member_id=?",Integer.class,member.id())).isEqualTo(1);}
 @Test @Tag("malicious") void currentQualificationRevocationCancelsProposal(){UUID id=join();offer(id);db.update("UPDATE listener_live_authorizations SET revoked_at=clock_timestamp() WHERE listener_id=?",listener.id());assertThat(queue.get(id,member.id()).get("status")).isEqualTo("SAFETY_TERMINATED");}
 @Test @Tag("confused") void unsupportedExplicitLanguageAndBoundedCapacityAreHonest(){assertThatThrownBy(()->queue.join(member.id(),new ListenerQueue.Admission(UUID.randomUUID(),"No matching language",false))).hasMessageContaining("No currently staffed");db.update("UPDATE listener_support_policy SET queue_capacity=1");join();var other=PhaseIFixtures.member(db,users,tokens);assertThatThrownBy(()->queue.join(other.id(),input())).hasMessageContaining("full");}
 @Test @Tag("happy") void erasureDeletesQueueAndItsEvents(){UUID id=join();offer(id);accounts.erase(member.id());assertThat(db.queryForObject("SELECT count(*) FROM listener_wait_queue WHERE id=?",Integer.class,id)).isZero();assertThat(db.queryForObject("SELECT count(*) FROM listener_queue_events WHERE queue_id=?",Integer.class,id)).isZero();}
 @Test @Tag("malicious") void listenerOfferedElsewhereCannotAlsoJoinAsMember(){UUID id=join();offer(id);assertThatThrownBy(()->queue.join(listener.id(),input())).hasMessageContaining("allocation conflicts");assertThat(db.queryForObject("SELECT count(*) FROM listener_wait_queue WHERE member_id=?",Integer.class,listener.id())).isZero();}
 @Test @Tag("malicious") void queuedListenerIsNotCoverageForOtherWaitingMembers(){var second=PhaseIFixtures.member(db,users,tokens);PhaseIFixtures.review(db,second.id(),staff.id(),true);coverage.approve(staff.id(),new ListenerQueueCoverage.Window(second.id(),now.minusSeconds(60),now.plusSeconds(14400)));live.setAvailability(second.id(),second.session(),0,true,null);queue.join(listener.id(),input());live.setAvailability(second.id(),second.session(),0,false,live.availability(second.id(),second.session()).leaseId());assertThatThrownBy(this::join).hasMessageContaining("No currently staffed");}
 @Test @Tag("happy") void genericNoticesAreOptionalDeduplicatedAndPreferenceAware(){db.update("UPDATE user_preferences SET notify_messages=TRUE WHERE user_id=?",member.id());UUID id=(UUID)queue.join(member.id(),new ListenerQueue.Admission(UUID.randomUUID(),null,true)).get("id");var q=offer(id);queue.work();assertThat(db.queryForObject("SELECT count(*) FROM listener_support_notices WHERE user_id=? AND entity_id=?",Integer.class,member.id(),id)).isEqualTo(2);clock(ListenerSupportPolicy.instant(q.get("allocation_expires_at")));queue.work();queue.work();assertThat(db.queryForObject("SELECT count(*) FROM listener_support_notices WHERE user_id=? AND entity_id=?",Integer.class,member.id(),id)).isEqualTo(3);assertThat(db.queryForList("SELECT body FROM notifications WHERE user_id=?",String.class,member.id())).allMatch(text->text.equals("Open GreenOcean to review an update."));var other=PhaseIFixtures.member(db,users,tokens);db.update("UPDATE user_preferences SET notify_messages=FALSE WHERE user_id=?",other.id());queue.join(other.id(),new ListenerQueue.Admission(UUID.randomUUID(),null,true));assertThat(db.queryForObject("SELECT count(*) FROM listener_support_notices WHERE user_id=?",Integer.class,other.id())).isZero();}
 @Test @Tag("confused") void briefReadinessGapKeepsOriginalWaitButNeverAdmitsNewMember(){UUID id=join();var original=queue.view(id,member.id()).get("expires_at");live.setAvailability(listener.id(),listener.session(),0,false,live.availability(listener.id(),listener.session()).leaseId());queue.work();assertThat(queue.view(id,member.id()).get("status")).isEqualTo("WAITING");assertThat(queue.view(id,member.id()).get("expires_at")).isEqualTo(original);var other=PhaseIFixtures.member(db,users,tokens);assertThatThrownBy(()->queue.join(other.id(),input())).hasMessageContaining("No currently staffed");live.setAvailability(listener.id(),listener.session(),0,true,null);queue.work();assertThat(queue.view(id,member.id()).get("status")).isEqualTo("OFFERED");assertThat(queue.view(id,member.id()).get("expires_at")).isEqualTo(original);}
 @Test @Tag("malicious") void databaseRejectsDeadlineRenewalAndTransferWithoutBoundRequest(){UUID id=join();var q=offer(id);db.execute("SAVEPOINT forbidden_queue_write");try{assertThatThrownBy(()->db.update("UPDATE listener_wait_queue SET expires_at=expires_at+INTERVAL '20 minutes' WHERE id=?",id)).isInstanceOf(org.springframework.dao.DataIntegrityViolationException.class);}finally{db.execute("ROLLBACK TO SAVEPOINT forbidden_queue_write");}db.execute("SAVEPOINT forbidden_queue_transfer");try{assertThatThrownBy(()->db.update("UPDATE listener_wait_queue SET status='TRANSFERRED' WHERE id=?",id)).isInstanceOf(org.springframework.dao.DataIntegrityViolationException.class);}finally{db.execute("ROLLBACK TO SAVEPOINT forbidden_queue_transfer");}assertThat(queue.view(id,member.id()).get("expires_at")).isEqualTo(q.get("expires_at"));assertThat(queue.view(id,member.id()).get("status")).isEqualTo("OFFERED");}
}
